universe u

-- [TABLET NODE: PowerCopiedLeft]
noncomputable def PowerCopiedLeft {Q : Type u} (r : Q → Q → Prop)
    (h : MultiSequence (PowerQ Q)) (x : IncSeq) (n : Nat) : Nat → PowerQ Q
  := by
-- BODY
    let rec go (m : Nat) : Nat → PowerQ Q
      | 0 =>
          PowerIResponse r (h (PowerShiftIter m x))
            (h (PowerShiftIter (m + 1) x))
      | k + 1 =>
          PowerIResponse r (go m k) (go (m + 1) k)
    exact go n

--- Tablet/PowerCopiedLeft.tex ---
\begin{definition}
Let $h$ be a multi-sequence with values in $\mathsf{PowerQ}(Q)$.  Define
$\mathsf{PowerCopiedLeft}_r(h,x,n,k)$ recursively on $k$.  At depth zero it
is the canonical Player I response to
\[
\bigl(h(\mathsf{PowerShiftIter}(n,x)),
h(\mathsf{PowerShiftIter}(n+1,x))\bigr).
\]
At depth $k+1$ it is the canonical response to the two values at depth $k$
in rows $n$ and $n+1$.  Thus row $n+1$ supplies exactly the copied right
move for row $n$, and the whole triangular play is a fixed function of the
raw values of $h$ on its shift orbit.
\end{definition}

--- Tablet/PowerIResponse.lean ---
import Tablet.PowerMove

universe u

-- [TABLET NODE: PowerIResponse]
noncomputable def PowerIResponse {Q : Type u} (r : Q → Q → Prop)
    (x y : PowerQ Q) : PowerQ Q :=
-- BODY
  by
    classical
    exact if h : ∃ x', PowerMove x x' ∧
        ∀ y', PowerMove y y' → ¬ PowerRel r x' y' then
      Classical.choose h
    else x

--- Tablet/PowerIResponse.tex ---
\begin{definition}
For a relation $r$ on $Q$, define the canonical Player I response
$\mathsf{PowerIResponse}_r(x,y)$ by choosing, when one exists, a legal move
$x'$ from $x$ such that every legal response $y'$ from $y$ leaves the pair
$(x',y')$ outside $\mathsf{PowerRel}(r)$.  If no such witness exists, use
$x$ itself.  The choice is made once as a function of the two raw
presentations, so it is independent of any later input multi-sequence.
\end{definition}

--- Tablet/PowerQ.lean ---
import Tablet.Preamble

universe u

-- [TABLET NODE: PowerQ]
inductive PowerQ (Q : Type u) : Type (u + 1) where
-- BODY
  | atom : Q → PowerQ Q
  | node : (ι : Type u) → Nonempty ι → (ι → PowerQ Q) → PowerQ Q

--- Tablet/PowerQ.tex ---
\begin{definition}
For a carrier $Q$, the full non-empty iterated powerset presentation
$\mathsf{PowerQ}(Q)$ is the inductive type generated by two disjoint tags.
An atom is a member $q\in Q$.  A node consists of an arbitrary nonempty
small index type $\iota$ and a family
$(X_i)_{i\in\iota}$ of already constructed presentations.  Thus a node
represents the nonempty set of its children, while the atom tag ensures that
an element of $Q$ is never confused with a set node.
\end{definition}

--- Tablet/PowerRel.lean ---
import Tablet.PowerChildWellFounded

universe u

-- [TABLET NODE: PowerRel]
def PowerRel {Q : Type u} (r : Q → Q → Prop) (x y : PowerQ Q) : Prop :=
-- BODY
  WellFounded.fix (C := fun _ : PowerQ Q × PowerQ Q => Prop)
    (WellFounded.prod_lex PowerChildWellFounded PowerChildWellFounded)
    (fun p rec => by
      rcases p with ⟨x, y⟩
      cases x with
      | atom q =>
        cases y with
        | atom q' => exact r q q'
        | node ι h g =>
          exact ∃ i, rec (.atom q, g i)
            (Prod.Lex.right _
              (show @PowerChild Q (g i) (.node ι h g) from ⟨i, rfl⟩))
      | node ι h f =>
        cases y with
        | atom q =>
          exact ∀ i, rec (f i, .atom q)
            (Prod.Lex.left _ _
              (show @PowerChild Q (f i) (.node ι h f) from ⟨i, rfl⟩))
        | node κ h' g =>
          exact ∀ i, ∃ j, rec (f i, g j)
            (Prod.Lex.left _ _
              (show @PowerChild Q (f i) (.node ι h f) from ⟨i, rfl⟩)))
    (x, y)

--- Tablet/PowerRel.tex ---
\begin{definition}
For a relation $r$ on $Q$, define the lifted relation
$\mathsf{PowerRel}(r)$ on the tagged hierarchy $\mathsf{PowerQ}(Q)$ by
well-founded recursion on the child relation.  For atoms $q,q'\in Q$,
\[
\mathsf{PowerRel}(r)(\mathsf{atom}(q),\mathsf{atom}(q'))
\quad\Longleftrightarrow\quad r(q,q').
\]
For a right node, an atom is related to it exactly when it is related to one
of its children.  A left node is related to an atom exactly when every one of
its children is related to that atom.  Finally, a left node is related to a
right node exactly when every left child is related to some right child.
The node may have any nonempty small index type; no branching restriction is
introduced.
\end{definition}

--- Tablet/PowerSupport.lean ---
import Tablet.PowerQ

universe u

-- [TABLET NODE: PowerSupport]
def PowerSupport {Q : Type u} : PowerQ Q → Set Q :=
-- BODY
  fun x => match x with
    | .atom q => {q}
    | .node _ _ f => ⋃ i, PowerSupport (f i)

--- Tablet/PowerSupport.tex ---
\begin{definition}
The support $\mathsf{PowerSupport}(X)\subseteq Q$ is defined by induction
on the presentation.  An atom $q$ has support $\{q\}$, and the support of
a node is the union of the supports of all of its children.  This is the
recursive version of the paper's transitive-closure support and records
exactly the atoms occurring below a presentation.
\end{definition}
