import Tablet.LocallyConstant
import Tablet.ShiftMap

universe u

-- [TABLET NODE: BadMultiSequence]
def BadMultiSequence {Q : Type u} (r : Q → Q → Prop) (h : MultiSequence Q) : Prop :=
-- BODY
  ∀ x, ¬ r (h x) (h (ShiftMap x))

--- Tablet/BadMultiSequence.tex ---
\begin{definition}
Let $r$ be a binary relation on $Q$.  A multi-sequence $h$ is bad for $r$ if
for every increasing enumeration $x$ one has
\[
\neg r\bigl(h(x),h(\mathsf{ShiftMap}(x))\bigr).
\]
For a quasi-order this is exactly the paper's condition
$h(N)\nleq h(\operatorname{shift}(N))$ for every infinite $N$.
\end{definition}

--- Tablet/MultiSequence.lean ---
import Tablet.IncSeq

universe u

-- [TABLET NODE: MultiSequence]
abbrev MultiSequence (E : Type u) :=
-- BODY
  IncSeq → E

--- Tablet/MultiSequence.tex ---
\begin{definition}
For a set $E$, a multi-sequence into $E$ is a map
$h:\mathsf{IncSeq}\to E$.  Through increasing enumerations this is the
paper's map from the infinite subsets of a base subset of $\mathbb N$ into
$E$.
\end{definition}

--- Tablet/IncSeq.lean ---
import Tablet.Preamble

-- [TABLET NODE: IncSeq]
abbrev IncSeq :=
-- BODY
  OrderEmbedding Nat Nat

--- Tablet/IncSeq.tex ---
\begin{definition}
An increasing sequence is an order embedding $\mathbb N\hookrightarrow
\mathbb N$.  We write $\mathsf{IncSeq}$ for the type of all such embeddings;
its elements are the increasing enumerations of infinite subsets of
$\mathbb N$.
\end{definition}

--- Tablet/IncSeqComp.lean ---
import Tablet.IncSeq

-- [TABLET NODE: IncSeqComp]
def IncSeqComp (f g : IncSeq) : IncSeq :=
-- BODY
  g.comp f

--- Tablet/IncSeqComp.tex ---
\begin{definition}
For $f,g\in\mathsf{IncSeq}$, their composition is the increasing embedding
$f\circ g$, written $\mathsf{IncSeqComp}(f,g)$.  Thus
$\mathsf{IncSeqComp}(f,g)(n)=f(g(n))$.
\end{definition}

--- Tablet/ShiftMap.lean ---
import Tablet.RightComp
import Tablet.SuccSeq

-- [TABLET NODE: ShiftMap]
def ShiftMap : IncSeq → IncSeq :=
-- BODY
  RightComp SuccSeq

--- Tablet/ShiftMap.tex ---
\begin{definition}
The shift map on increasing enumerations is right composition by the
successor: $\mathsf{ShiftMap}(f)=f\circ\mathsf{SuccSeq}$.  Under the
identification with infinite subsets of $\mathbb N$, this removes the least
element of the subset.
\end{definition}

--- Tablet/PowerShiftIter.lean ---
import Tablet.ShiftMap

-- [TABLET NODE: PowerShiftIter]
def PowerShiftIter : Nat → IncSeq → IncSeq :=
-- BODY
  fun n x => Nat.rec x (fun _ z => ShiftMap z) n

--- Tablet/PowerShiftIter.tex ---
\begin{definition}
For an increasing enumeration $x$ and $n\in\mathbb N$, define
$\mathsf{PowerShiftIter}(n,x)$ recursively by
\[
\mathsf{PowerShiftIter}(0,x)=x,qquad
\mathsf{PowerShiftIter}(n+1,x)=mathsf{ShiftMap} igl(
\mathsf{PowerShiftIter}(n,x)\bigr).
\]
This is the $n$-fold shift orbit used by the copied games.
\end{definition}

--- Tablet/PowerChild.lean ---
import Tablet.PowerQ

universe u

-- [TABLET NODE: PowerChild]
def PowerChild {Q : Type u} : PowerQ Q → PowerQ Q → Prop :=
-- BODY
  fun x y => match y with
    | .atom _ => False
    | .node _ _ f => ∃ i, x = f i

--- Tablet/PowerChild.tex ---
\begin{definition}
For presentations $x,y\in\mathsf{PowerQ}(Q)$, write
$\mathsf{PowerChild}(x,y)$ when $y$ is a node and $x$ is one of the
children displayed by its indexing family.  Atoms have no children.  The
orientation is child-to-parent: this is the relation that decreases when a
recursive comparison moves down the hierarchy.
\end{definition}

--- Tablet/RightComp.lean ---
import Tablet.IncSeqComp

-- [TABLET NODE: RightComp]
def RightComp (g : IncSeq) (f : IncSeq) : IncSeq :=
-- BODY
