--- Tablet/RightComp.tex ---
\begin{definition}
For $g\in\mathsf{IncSeq}$, right composition by $g$ is the map
$\mathsf{RightComp}(g):\mathsf{IncSeq}\to\mathsf{IncSeq}$ defined by
$\mathsf{RightComp}(g)(f)=f\circ g$.
\end{definition}

--- Tablet/SuccSeq.lean ---
import Tablet.IncSeq

-- [TABLET NODE: SuccSeq]
def SuccSeq : IncSeq :=
-- BODY
  OrderEmbedding.ofStrictMono (fun n : Nat => n + 1) (by
    intro a b hab
    exact Nat.add_lt_add_right hab 1)

--- Tablet/SuccSeq.tex ---
\begin{definition}
The successor increasing sequence is the order embedding
$\mathsf{SuccSeq}:\mathbb N\hookrightarrow\mathbb N$ given by
$\mathsf{SuccSeq}(n)=n+1$.
\end{definition}
